<script setup lang="ts">import type {Workbench} from '../app/useWorkbench';import PathField from '../shared/PathField.vue';import JsonReport from '../shared/JsonReport.vue';import DiscoveryPanel from './DiscoveryPanel.vue';import {openPath} from '../shared/desktop';const {w}=defineProps<{w:Workbench}>();const s=w.s;</script>
<template><div class="page-heading"><div><div class="eyebrow">ENVIRONMENT & PATHS</div><h1>环境与路径</h1><p>配置存储在独立的桌面用户目录，安装资源保持只读。</p></div><el-button @click="w.exportDiagnostics">导出诊断信息</el-button></div><section class="card" data-testid="settings"><div class="card-heading"><span class="card-icon">D</span><div><h2>桌面环境</h2><p>本机运行状态与应用数据位置</p></div></div><dl class="definition-list"><dt>应用版本</dt><dd>{{s.info.version||'0.1.0'}} · {{s.info.channel||'开发版'}}</dd><dt>用户数据目录</dt><dd class="mono">{{s.info.dataDir||s.info.data_dir||'由桌面外壳管理'}}</dd><dt>安装资源目录</dt><dd class="mono">{{s.info.resourceRoot||s.info.resource_root||'由桌面外壳管理'}}</dd></dl><div class="button-row"><el-button @click="openPath(s.info.dataDir||s.info.data_dir)">打开用户数据目录</el-button><el-button @click="w.exportConfiguration">导出配置快照</el-button><el-button @click="s.view='workbench';s.stage=0">管理项目与工具链</el-button></div><div class="subsection"><h3>工作空间偏好</h3><el-alert v-if="s.preferenceRecovery?.available" :title="s.preferenceRecovery.message" type="warning" :closable="false"/><div class="option-row"><el-checkbox v-model="s.logFollow">日志自动跟随新输出</el-checkbox><el-checkbox v-model="s.preferences.compact_mode">紧凑工作空间</el-checkbox></div><el-button @click="w.savePreferences" type="primary" plain :disabled="!!s.pending">保存偏好</el-button></div></section><DiscoveryPanel :w="w"/><section class="card"><div class="card-heading"><span class="card-icon lilac">↥</span><div><h2>导入旧平台配置</h2><p>先预览项目与工具链，再导入隔离的桌面数据目录</p></div></div><PathField v-model="s.legacyRoot" label="旧平台根目录"/><div class="subsection"><h3>可选 · 路径前缀重新定位</h3><p>仅重新定位已确认的项目、工具链和任务对应关系。逐项预览本机路径与可达性，源文件、运行 XML 和历史内容保持原样。</p><div class="form-grid"><PathField v-model="s.pathMappingFrom" label="旧目录前缀" hint="可手动填写已不存在的旧目录" data-testid="legacy-prefix-from"/><PathField v-model="s.pathMappingTo" label="本机新目录前缀" hint="选择本机对应目录后重新预览" data-testid="legacy-prefix-to"/></div></div><div class="option-row"><el-checkbox v-model="s.includeLegacyHistory" @change="s.legacyPreview=null">同时导入已结束运行的日志与归档</el-checkbox><span class="muted">不复制原结果目录；原平台与业务资源保持原样</span></div><div class="button-row"><el-button @click="w.previewLegacy" :disabled="!s.legacyRoot||!!s.pending||s.runtime.busy">预览导入范围</el-button><el-button type="primary" @click="w.importLegacy" :disabled="!s.legacyPreview||s.legacyPreview.source_root!==s.legacyRoot||!!s.pending||s.runtime.busy">确认导入配置</el-button></div><template v-if="s.legacyPreview"><div class="summary-counters"><div><strong>{{s.legacyPreview.summary?.projects||0}}</strong><span>项目档案</span></div><div><strong>{{s.legacyPreview.summary?.bindings||0}}</strong><span>任务对应关系</span></div><div><strong>{{s.legacyPreview.summary?.machine_fields||0}}</strong><span>工具链字段</span></div><div v-if="s.includeLegacyHistory"><strong>{{s.legacyPreview.summary?.history_sessions||0}}</strong><span>已结束会话</span></div></div><el-alert v-for="warning in s.legacyPreview.warnings||[]" :key="warning" :title="warning" type="warning" :closable="false" class="spaced-alert"/><el-table :data="s.legacyPreview.projects||[]"><el-table-column prop="path" label="项目路径"/><el-table-column label="本机状态" width="160"><template #default="{row}"><el-tag :type="row.exists?'success':'warning'">{{row.exists?'目录存在':'需要重新定位'}}</el-tag></template></el-table-column></el-table><h3 v-if="s.legacyPreview.path_changes?.length" class="spaced-alert">路径重新定位预览</h3><el-table v-if="s.legacyPreview.path_changes?.length" :data="s.legacyPreview.path_changes" data-testid="legacy-path-changes"><el-table-column prop="field" label="字段" min-width="130"/><el-table-column prop="old" label="原路径" min-width="180"/><el-table-column prop="new" label="本机目标路径" min-width="180"/><el-table-column label="本机核验" width="125"><template #default="{row}"><el-tag :type="row.exists?'success':'warning'">{{row.exists?'路径存在':'需要重新定位'}}</el-tag></template></el-table-column></el-table><JsonReport :data="s.legacyPreview" title="查看完整导入范围与冲突"/></template><el-alert v-if="s.needsRefresh" title="导入完成。刷新项目状态后可选择导入的档案。" type="success" :closable="false"/></section><section class="card"><div class="card-heading"><span class="card-icon amber">A</span><div><h2>高级维护 · 平台配置归档</h2><p>仅处理可核验的平台历史 XML、任务单、manifest 与 VS 启动条目</p></div></div><div class="info-box">保留当前配置、手写文件与来源不明文件；业务输出与原始 XML 不参与清理。文件将移动到维护归档，执行前必须核对清单。</div><div class="button-row"><el-button @click="w.previewCleanup" :disabled="!!s.pending||s.runtime.busy">预览清理范围</el-button><el-popconfirm title="确认将预览中可核验的平台文件移入维护归档？" @confirm="w.cleanup"><template #reference><el-button type="warning" :disabled="!s.cleanup?.files?.length||!!s.pending||s.runtime.busy">归档预览中的文件</el-button></template></el-popconfirm></div><template v-if="s.cleanup"><el-table :data="s.cleanup.files||[]" empty-text="没有可安全归档的平台历史文件"><el-table-column prop="path" label="待归档文件"/><el-table-column prop="kind" label="归属" width="160"/></el-table><JsonReport :data="s.cleanup" title="查看保留、跳过与归档范围"/></template></section></template>
